```javascript
const { Client, GatewayIntentBits } = require('discord.js');

// Créer un client Discord
const client = new Client({
  intents: [
    GatewayIntentBits.Guilds,
    GatewayIntentBits.GuildMessages,
    GatewayIntentBits.MessageContent
  ]
});

// Connexion du client au serveur Discord
client.on('ready', () => {
  console.log(`Bot ${client.user.tag} connecté`);
});

// Écouteur d'événements de commande slash
client.on('interactionCreate', async interaction => {
  if (!interaction.isChatInputCommand()) return;

  const { commandName } = interaction;

  if (commandName === 'bannir') {
    // Vérifier si l'utilisateur a les permissions nécessaires
    if (!interaction.member.permissions.has('BAN_MEMBERS')) {
      return interaction.reply({
        content: 'Vous n'avez pas la permission de bannir des utilisateurs.',
        ephemeral: true // Réponse privée
      });
    }

    // Vérifier si l'utilisateur cible est un membre du serveur
    const member = interaction.guild.members.cache.get(interaction.options.getMember('utilisateur').id);
    if (!member) {
      return interaction.reply({
        content: 'Cet utilisateur n'est pas présent dans le serveur.',
        ephemeral: true // Réponse privée
      });
    }

    // Bannir l'utilisateur cible
    try {
      await interaction.guild.ban(member, { days: 0, reason: `Banni par ${interaction.user.tag}` });
      return interaction.reply({ content: `L'utilisateur ${member.user.tag} a été banni.` });
    } catch (error) {
      console.error(error);
      return interaction.reply({
        content: 'Une erreur est survenue lors du bannissement de l'utilisateur.',
        ephemeral: true // Réponse privée
      });
    }
  }
});

// Connexion du client au serveur Discord
client.login(process.env.TOKEN);
```

Cette commande "bannir" utilise la commande slash pour recevoir des interactions de chat. Elle vérifie les permissions de l'utilisateur avant de bannir l'utilisateur cible et affiche une réponse privée si une erreur se produit.

