```cpp
#include <boost/markdown.hpp>

std::string markdown_to_html(const std::string& markdown) {
    boost::optional<boost::text::markdown::parser<>::result_type> html_result =
        boost::text::markdown::parser<>().parse(markdown);
    if (!html_result) {
        // Handle error parsing Markdown
        return ""; // ou une autre valeur de retour appropriée
    }
    std::string html_output;
    boost::text::markdown::renderer<>::options renderer_options;
    boost::text::markdown::renderer<> renderer(renderer_options);
    renderer.render(*html_result, html_output);
    return html_output;
}
```

